def fetch_bts_geospatial_catalog(self, **kwargs):
    """
    Fetch collection-level metadata from BTS Geospatial Data Catalog (data.transportation.gov).

    This function supports two modes:
    1. Collection-level: Use dataset_shortname (e.g., "NTAD") to search the catalog API
       and return all matching dataset metadata as a collection.
    2. Item-level: Use uuid (Socrata 4x4 dataset ID) to fetch detailed metadata via the views API.

    Parameters via kwargs:
    - dataset_shortname: e.g., "NTAD" for National Transportation Atlas Database
    - uuid or official_website_id: Socrata 4x4 dataset ID (e.g., "dkbd-kjgw")
    - doi: DOI string for fallback text search
    """
    import json
    import urllib.parse

    base_url = "https://data.transportation.gov"

    # Strategy 1: Direct dataset ID -> use views API for rich metadata
    dataset_id = kwargs.get('uuid') or kwargs.get('official_website_id')
    if dataset_id:
        url = f"{base_url}/api/views/{dataset_id}"
        resp = self._get_with_retry(url)
        try:
            data = json.loads(resp)
            return {"source": "BTS-Geospatial-Catalog", "data": data}
        except json.JSONDecodeError:
            return {"error": f"Failed to parse JSON from views API: {resp[:200]}"}

    # Strategy 2: Collection-level search by shortname
    shortname = kwargs.get('dataset_shortname')
    search_term = shortname
    if not search_term:
        # Fallback: use DOI as search term
        doi = kwargs.get('doi')
        if doi:
            search_term = doi

    if search_term:
        encoded_q = urllib.parse.quote(search_term)
        url = f"{base_url}/api/catalog/v1?q={encoded_q}&only=datasets&limit=200"
        resp = self._get_with_retry(url)
        try:
            data = json.loads(resp)
            # Structure as collection-level metadata
            return {
                "source": "BTS-Geospatial-Catalog",
                "data": {
                    "collection_query": search_term,
                    "total_results": data.get("resultSetSize", len(data.get("results", []))),
                    "datasets": data.get("results", [])
                }
            }
        except json.JSONDecodeError:
            return {"error": f"Failed to parse JSON from catalog API: {resp[:200]}"}

    return {"error": "No valid identifier provided. Provide uuid, dataset_shortname, or doi."}

