def fetch_bts_geospatial_catalog(self, **kwargs):
    """
    Fetch collection- or item-level metadata from BTS Geospatial Data Catalog 
    (data.transportation.gov - Socrata-based open data portal).

    Two strategies:

    **Strategy A (Item-level)**: If `uuid` or `official_website_id` is provided
    (a Socrata 4x4 identifier like "dkbd-kjgw"), hit the Socrata Views API:
        GET https://data.transportation.gov/api/views/{id}
    Returns rich metadata about that single dataset.

    **Strategy B (Collection-level)**: If a `dataset_shortname` (e.g. "NTAD") or
    `doi` is provided, fetch the full DCAT-US catalog from /data.json and filter
    for datasets whose metadata contains the search term. This yields a 
    de facto "collection" view of all datasets belonging to NTAD.
    """
    import json

    BASE = "https://data.transportation.gov"

    # ── Strategy A: item-level via Socrata Views API ──
    dataset_id = kwargs.get('uuid') or kwargs.get('official_website_id')
    if dataset_id:
        url = f"{BASE}/api/views/{dataset_id}"
        resp = self._get_with_retry(url)
        resp_text = resp.text if hasattr(resp, 'text') else str(resp)
        try:
            return {"source": "BTS-Geospatial-Catalog", "data": json.loads(resp_text)}
        except json.JSONDecodeError:
            return {"error": f"Views API returned non-JSON: {resp_text[:300]}"}

    # ── Strategy B: collection-level via DCAT-US /data.json ──
    shortname = (kwargs.get('dataset_shortname') or '').strip()
    doi = (kwargs.get('doi') or '').strip()
    if not shortname and not doi:
        return {"error": "Provide uuid, dataset_shortname, or doi."}

    url = f"{BASE}/data.json"
    resp = self._get_with_retry(url)
    resp_text = resp.text if hasattr(resp, 'text') else str(resp)

    try:
        catalog = json.loads(resp_text)
    except json.JSONDecodeError:
        return {"error": f"/data.json returned non-JSON: {resp_text[:300]}"}

    datasets = catalog.get('dataset', [])
    terms = [t.lower() for t in (shortname, doi) if t]

    matched = []
    for ds in datasets:
        haystack = json.dumps(ds).lower()
        if any(term in haystack for term in terms):
            matched.append(ds)

    return {
        "source": "BTS-Geospatial-Catalog",
        "data": {
            "catalog_description": catalog.get('describedBy', ''),
            "total_in_catalog": len(datasets),
            "matched_count": len(matched),
            "search_terms": terms,
            "datasets": matched
        }
    }

