import re
import json
import requests

class ZenodoMetadataFetcher:
    """Zenodo 数据集集合级元数据获取器"""

    def __init__(self):
        self.session = requests.Session()
        self.session.headers.update({
            'User-Agent': 'Mozilla/5.0 (compatible; MetadataFetcher/1.0)'
        })

    def _get_with_retry(self, url, headers=None, max_retries=3):
        """带重试的 HTTP GET 请求"""
        for attempt in range(max_retries):
            try:
                resp = self.session.get(url, headers=headers or {}, timeout=30)
                return resp
            except requests.RequestException as e:
                if attempt == max_retries - 1:
                    raise e
        return None

    def _extract_record_id(self, dataset_url=None, doi=None):
        """
        从 dataset_url 或 doi 中提取 Zenodo record ID。

        Zenodo URL 格式:
          - https://zenodo.org/records/{record_id}
          - https://zenodo.org/record/{record_id}

        Zenodo DOI 格式:
          - 10.5281/zenodo.{record_id}
        """
        # 策略1：从 URL 中提取
        if dataset_url:
            match = re.search(r'zenodo\.org/(?:records?|api/records)/(\d+)', dataset_url)
            if match:
                return match.group(1)

        # 策略2：从 DOI 中提取
        if doi:
            match = re.search(r'zenodo[./](\d+)', doi)
            if match:
                return match.group(1)

        return None

    def fetch_zenodo(self, **kwargs):
        """
        从 Zenodo REST API 获取数据集完整元数据。

        可用参数:
          - dataset_url: Zenodo 数据集页面 URL
          - doi: Zenodo DOI (如 10.5281/zenodo.17260370)
          - uuid / official_website_id: 直接传入 Zenodo record ID
        """
        # 确定 record ID
        record_id = (
            kwargs.get('uuid') or 
            kwargs.get('official_website_id') or
            None
        )

        if not record_id:
            record_id = self._extract_record_id(
                dataset_url=kwargs.get('dataset_url'),
                doi=kwargs.get('doi')
            )

        if not record_id:
            return {"error": "无法从提供的参数中提取 Zenodo record ID。请提供 dataset_url、doi 或 uuid。"}

        # 构建 API URL
        api_url = f"https://zenodo.org/api/records/{record_id}"

        try:
            resp = self._get_with_retry(api_url)

            if resp.status_code == 200:
                data = resp.json()
                return {
                    "source": "Zenodo-Custom",
                    "data": data
                }
            elif resp.status_code == 404:
                return {"error": f"Zenodo record {record_id} 未找到。"}
            elif resp.status_code in (401, 403):
                return {"error": f"Zenodo API 需要鉴权 (HTTP {resp.status_code})。"}
            else:
                return {"error": f"Zenodo API 返回非预期状态码: {resp.status_code}"}

        except Exception as e:
            return {"error": f"请求 Zenodo API 时发生异常: {str(e)}"}


