    Extracts XML metadata path from doi_landing_page URL, fetches ISO 19115-2 XML,
    and parses it into structured JSON.
    """
    import xml.etree.ElementTree as ET
    from urllib.parse import urlparse, parse_qs, unquote

    doi_landing_page = kwargs.get('doi_landing_page', '')
    dataset_url = kwargs.get('dataset_url', '')
    doi = kwargs.get('doi', '')

    # Step 1: Extract XML path from doi_landing_page
    xml_path = None

    if doi_landing_page:
        parsed = urlparse(doi_landing_page)
        params = parse_qs(parsed.query)
        if 'xml' in params:
            xml_path = params['xml'][0]

    # Step 2: If no doi_landing_page, try to derive from dataset_url product page
    if not xml_path and dataset_url:
        try:
            resp = self._get_with_retry(dataset_url)
            if resp and resp.status_code == 200:
                html = resp.text
                match = re.search(r'xml=([^"&\s]+\.xml)', html)
                if match:
                    xml_path = unquote(match.group(1))
                if not xml_path:
                    match = re.search(r'ngdc\.noaa\.gov/metadata/published/([^"&\s]+\.xml)', html)
                    if match:
                        xml_path = match.group(1)
                if not xml_path:
                    match = re.search(r'metadata/landing-page[^"]*[?&]id=([^"&\s]+)', html)
                    if match:
                        metadata_id = unquote(match.group(1))
                        iso_url = "https://www.ncei.noaa.gov/access/metadata/landing-page/bin/iso?id=" + metadata_id
                        resp2 = self._get_with_retry(iso_url)
                        if resp2 and resp2.status_code == 200:
                            return _parse_landing_page_html(resp2.text, doi, dataset_url)
        except Exception:
            pass

    if not xml_path:
        return {"error": "Could not derive XML metadata path from provided parameters"}

    # Step 3: Construct ISO XML metadata URL
    xml_path = xml_path.strip('/')
    iso_url = "https://www.ngdc.noaa.gov/metadata/published/" + xml_path

    # Step 4: Fetch and parse XML
    try:
        resp = self._get_with_retry(iso_url)
        if not resp or resp.status_code != 200:
            return {"error": "Failed to fetch ISO XML metadata: HTTP " + str(resp.status_code if resp else 'no response')}

        xml_content = resp.text
        root = ET.fromstring(xml_content)

        ns = {
            'gmd': 'http://www.isotc211.org/2005/gmd',
            'gco': 'http://www.isotc211.org/2005/gco',
            'gmi': 'http://www.isotc211.org/2005/gmi',
            'gml': 'http://www.opengis.net/gml/3.2',
            'xlink': 'http://www.w3.org/1999/xlink',
        }

        result = {"source": "NOAA-NCEI-Custom", "data": {}}
        data = result["data"]

        # --- Title ---
        title_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:title/gco:CharacterString', ns)
        if title_el is not None:
            data["title"] = title_el.text

        # --- Alternate Title ---
        alt_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:alternateTitle/gco:CharacterString', ns)
        if alt_el is not None:
            data["alternate_title"] = alt_el.text

        # --- Abstract ---
        abstract_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:abstract/gco:CharacterString', ns)
        if abstract_el is not None:
            data["abstract"] = abstract_el.text

        # --- DOI ---
        doi_found = doi
        if not doi_found:
            doi_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:identifier/gmd:MD_Identifier/gmd:code/gco:CharacterString', ns)
            if doi_el is not None:
                doi_found = doi_el.text
        if doi_found:
            data["doi"] = doi_found

        # --- Metadata ID ---
        file_id_el = root.find('.//gmd:fileIdentifier/gco:CharacterString', ns)
        if file_id_el is not None:
            data["metadata_id"] = file_id_el.text

        # --- Keywords ---
        keywords = []
        for kw_el in root.findall('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:descriptiveKeywords/gmd:MD_Keywords/gmd:keyword/gco:CharacterString', ns):
            if kw_el.text:
                keywords.append(kw_el.text)
        if keywords:
            data["keywords"] = keywords

        # --- Credit ---
        credit_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:credit/gco:CharacterString', ns)
        if credit_el is not None:
            data["credit"] = credit_el.text

        # --- Authors ---
        authors = []
        for party_el in root.findall('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:citedResponsibleParty/gmd:CI_ResponsibleParty', ns):
            org_el = party_el.find('gmd:organisationName/gco:CharacterString', ns)
            role_el = party_el.find('gmd:role/gmd:CI_RoleCode', ns)
            ind_el = party_el.find('gmd:individualName/gco:CharacterString', ns)
            author_info = {}
            if org_el is not None and org_el.text:
                author_info["organization"] = org_el.text
            if ind_el is not None and ind_el.text:
                author_info["individual"] = ind_el.text
            if role_el is not None:
                code = role_el.get('codeListValue') or role_el.text
                author_info["role"] = code
            if author_info:
                authors.append(author_info)
        if authors:
            data["authors"] = authors

        # --- Publication Date ---
        pub_date_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:date/gmd:CI_Date/gmd:date/gco:Date', ns)
        if pub_date_el is not None and pub_date_el.text:
            data["publication_date"] = pub_date_el.text

        # --- Status ---
        status_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:status/gmd:MD_ProgressCode', ns)
        if status_el is not None:
            data["status"] = status_el.get('codeListValue') or status_el.text

        # --- Bounding Box ---
        west_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:extent/gmd:EX_Extent/gmd:geographicElement/gmd:EX_GeographicBoundingBox/gmd:westBoundLongitude/gco:Decimal', ns)
        east_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:extent/gmd:EX_Extent/gmd:geographicElement/gmd:EX_GeographicBoundingBox/gmd:eastBoundLongitude/gco:Decimal', ns)
        south_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:extent/gmd:EX_Extent/gmd:geographicElement/gmd:EX_GeographicBoundingBox/gmd:southBoundLatitude/gco:Decimal', ns)
        north_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:extent/gmd:EX_Extent/gmd:geographicElement/gmd:EX_GeographicBoundingBox/gmd:northBoundLatitude/gco:Decimal', ns)

        bbox = {}
        if west_el is not None:
            bbox["west"] = float(west_el.text)
        if east_el is not None:
            bbox["east"] = float(east_el.text)
        if south_el is not None:
            bbox["south"] = float(south_el.text)
        if north_el is not None:
            bbox["north"] = float(north_el.text)
        if bbox:
            data["spatial_extent"] = bbox

        # --- Distribution Links ---
        transfer_urls = []
        for tr_el in root.findall('.//gmd:distributionInfo/gmd:MD_Distribution/gmd:transferOptions/gmd:MD_DigitalTransferOptions/gmd:onLine/gmd:CI_OnlineResource', ns):
            link_el = tr_el.find('gmd:linkage/gmd:URL', ns)
            desc_el = tr_el.find('gmd:description/gco:CharacterString', ns)
            protocol_el = tr_el.find('gmd:protocol/gco:CharacterString', ns)
            url_info = {}
            if link_el is not None and link_el.text:
                url_info["url"] = link_el.text
            if desc_el is not None and desc_el.text:
                url_info["description"] = desc_el.text
            if protocol_el is not None and protocol_el.text:
                url_info["protocol"] = protocol_el.text
            if url_info:
                transfer_urls.append(url_info)
        if transfer_urls:
            data["distribution_links"] = transfer_urls

        # --- Point of Contact ---
        contact_el = root.find('.//gmd:contact/gmd:CI_ResponsibleParty', ns)
        if contact_el is not None:
            contact_org = contact_el.find('gmd:organisationName/gco:CharacterString', ns)
            contact_email = contact_el.find('.//gmd:address/gmd:CI_Address/gmd:electronicMailAddress/gco:CharacterString', ns)
            contact_info = {}
            if contact_org is not None and contact_org.text:
                contact_info["organization"] = contact_org.text
            if contact_email is not None and contact_email.text:
                contact_info["email"] = contact_email.text
            if contact_info:
                data["point_of_contact"] = contact_info

        # --- Lineage ---
        lineage_el = root.find('.//gmd:dataQualityInfo/gmd:DQ_DataQuality/gmd:lineage/gmd:LI_Lineage/gmd:statement/gco:CharacterString', ns)
        if lineage_el is not None and lineage_el.text:
            data["lineage"] = lineage_el.text

        # --- Product Page ---
        if dataset_url:
            data["product_page"] = dataset_url

        return result

    except ET.ParseError as e:
        return {"error": "XML parsing error: " + str(e)}
    except Exception as e:
        return {"error": "Unexpected error: " + str(e)}


