from urllib.parse import urlparse, parse_qs, unquote

def fetch_ncei_geoportal(self, **kwargs):
    """Fetch collection-level metadata from NOAA NCEI via the Geoportal REST API."""
    doi = kwargs.get('doi', '')
    dataset_url = kwargs.get('dataset_url', '')
    doi_landing_page = kwargs.get('doi_landing_page', '')
    dataset_name = kwargs.get('dataset_name', '')

    metadata_id = None

    # Strategy 1: Extract metadata ID from doi_landing_page URL
    if doi_landing_page:
        parsed = urlparse(doi_landing_page)
        params = parse_qs(parsed.query)
        xml_path = params.get('xml', [None])[0]
        if xml_path:
            xml_path = unquote(xml_path)
            # Extract short name from filename: etopo_2022.xml -> etopo_2022
            filename_match = re.search(r'/([^/]+)\.xml$', xml_path)
            if filename_match:
                short_name = filename_match.group(1)
                # Extract path hierarchy for namespace construction
                # Path like: NOAA/NESDIS/NGDC/MGG/DEM//iso/xml/etopo_2022.xml
                path_parts = [p for p in xml_path.replace('//', '/').split('/') if p]
                # Find 'iso' and take parts before it (excluding NOAA, NESDIS at top)
                iso_idx = None
                for i, part in enumerate(path_parts):
                    if part.lower() == 'iso':
                        iso_idx = i
                        break
                if iso_idx and iso_idx >= 2:
                    # Parts between top-level orgs and 'iso': skip NOAA, NESDIS, take ngdc, mgg, dem
                    ns_parts = path_parts[2:iso_idx]  # skip NOAA, NESDIS
                    if ns_parts:
                        namespace = '.'.join(ns_parts).lower()
                        metadata_id = f"gov.noaa.{namespace}:{short_name}"
                        print(f"[DEBUG] Constructed metadata_id from doi_landing_page: {metadata_id}")

    # Strategy 2: Try from doi_landing_page content - extract NCEI Metadata ID from HTML text
    if not metadata_id and doi_landing_page:
        try:
            resp = self._get_with_retry(doi_landing_page)
            if resp and resp.status_code == 200:
                html_text = resp.text
                # Look for "NCEI Metadata ID: gov.noaa.xxx" pattern in HTML
                m = re.search(r'NCEI\s+Metadata\s+ID:\s*(gov\.noaa\.[\w.]+:[\w_]+)', html_text, re.IGNORECASE)
