            result['publicationDate'] = pub_date_el.text
        else:
            pub_date_el = root.find('.//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:date/gmd:CI_Date/gmd:date/gco:Date', ns)
