import re
import xml.etree.ElementTree as ET
import json
import urllib.parse

def fetch_ncei_etopo(self, **kwargs):
    """
    Fetch collection-level metadata for NOAA NCEI datasets using NCEI-native APIs.

    Strategy (waterfall):
    1. DOI landing page -> extract XML path -> fetch NCEI ISO XML -> parse
    2. Dataset URL -> extract NCEI metadata ID -> use landing page JSON-LD
    3. DOI landing page -> extract NCEI metadata ID -> use landing page JSON-LD
    4. DataCite API as fallback
    """
    doi = kwargs.get("doi", "")
    doi_landing_page = kwargs.get("doi_landing_page", "")
    dataset_url = kwargs.get("dataset_url", "")
    dataset_name = kwargs.get("dataset_name", "")

    # Namespaces for ISO 19115-2 XML parsing
    ISO_NS = {
        "gmd": "http://www.isotc211.org/2005/gmd",
        "gco": "http://www.isotc211.org/2005/gco",
        "gmi": "http://www.isotc211.org/2005/gmi",
        "gml": "http://www.opengis.net/gml/3.2",
        "gmx": "http://www.isotc211.org/2005/gmx",
    }

    ncei_metadata_id = None
    xml_path = None

    # --- Extract XML path from DOI landing page ---
    if doi_landing_page:
        match = re.search(r'[?&]xml=([^&]+)', doi_landing_page)
        if match:
            xml_path = urllib.parse.unquote(match.group(1))

    # --- Extract NCEI Metadata ID from various sources ---
    if not ncei_metadata_id and dataset_url:
        # Pattern: id=gov.noaa.ngdc.mgg.dem:etopo_2022
        match = re.search(r'id=([^&]+)', dataset_url)
        if match:
            ncei_metadata_id = urllib.parse.unquote(match.group(1))

    # --- Strategy 1: NCEI ISO XML endpoint ---
    if xml_path:
        xml_url = f"https://www.ngdc.noaa.gov/metadata/published/{xml_path}"
        resp = self._get_with_retry(xml_url)
        if resp is not None and resp.status_code == 200:
            try:
                root = ET.fromstring(resp.text)
                result = {}

                # File identifier
                el = root.find(".//gmd:fileIdentifier/gco:CharacterString", ISO_NS)
                if el is not None and el.text:
                    result["fileIdentifier"] = el.text
                    if not ncei_metadata_id:
                        ncei_metadata_id = el.text

                # Language
                el = root.find(".//gmd:language/gco:CharacterString", ISO_NS)
                if el is not None and el.text:
                    result["language"] = el.text

                # Title
                el = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:title/gco:CharacterString", ISO_NS)
                if el is not None and el.text:
                    result["title"] = el.text

                # Alternate title
                el = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:alternateTitle/gco:CharacterString", ISO_NS)
                if el is not None and el.text:
                    result["alternateTitle"] = el.text

                # Abstract / Description
                el = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:abstract/gco:CharacterString", ISO_NS)
                if el is not None and el.text:
                    result["description"] = el.text

                # Purpose
                el = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:purpose/gco:CharacterString", ISO_NS)
                if el is not None and el.text:
                    result["purpose"] = el.text

                # Status / Progress code
                el = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:status/gmd:MD_ProgressCode", ISO_NS)
                if el is not None:
                    result["status"] = el.get("codeListValue", "") if el.get("codeListValue") else el.text

                # DOI
                el = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:identifier/gmd:MD_Identifier/gmd:code/gco:CharacterString", ISO_NS)
                if el is not None and el.text:
                    result["doi"] = el.text

                # Citation date
                date_el = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:date/gmd:CI_Date/gmd:date/gco:Date", ISO_NS)
                date_type_el = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:date/gmd:CI_Date/gmd:dateType/gmd:CI_DateTypeCode", ISO_NS)
                if date_el is not None and date_el.text:
                    result["publicationDate"] = date_el.text
                    if date_type_el is not None:
                        result["dateType"] = date_type_el.get("codeListValue", date_type_el.text if date_type_el.text else "")

                # All dates
                dates = []
                for cite_date in root.findall(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:date/gmd:CI_Date", ISO_NS):
                    d_el = cite_date.find("gmd:date/gco:Date", ISO_NS)
                    dt_el = cite_date.find("gmd:dateType/gmd:CI_DateTypeCode", ISO_NS)
                    if d_el is not None and d_el.text:
                        dates.append({
                            "date": d_el.text,
                            "dateType": dt_el.get("codeListValue", "") if dt_el is not None else ""
                        })
                if dates:
                    result["dates"] = dates

                # Organisation / Point of contact
                orgs = []
                for rp in root.findall(".//gmd:contact/gmd:CI_ResponsibleParty", ISO_NS):
                    org_el = rp.find("gmd:organisationName/gco:CharacterString", ISO_NS)
                    role_el = rp.find("gmd:role/gmd:CI_RoleCode", ISO_NS)
                    email_el = rp.find(".//gmd:electronicMailAddress/gco:CharacterString", ISO_NS)
                    org_info = {}
                    if org_el is not None and org_el.text:
                        org_info["name"] = org_el.text
                    if role_el is not None:
                        org_info["role"] = role_el.get("codeListValue", "")
                    if email_el is not None and email_el.text:
                        org_info["email"] = email_el.text
                    if org_info:
                        orgs.append(org_info)
                if orgs:
                    result["contacts"] = orgs

                # Also check cited responsible party (originator/publisher)
                for rp in root.findall(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:citation/gmd:CI_Citation/gmd:citedResponsibleParty/gmd:CI_ResponsibleParty", ISO_NS):
                    org_el = rp.find("gmd:organisationName/gco:CharacterString", ISO_NS)
                    role_el = rp.find("gmd:role/gmd:CI_RoleCode", ISO_NS)
                    if org_el is not None and org_el.text:
                        found = False
                        for o in orgs:
                            if o.get("name") == org_el.text:
                                found = True
                                break
                        if not found:
                            orgs.append({
                                "name": org_el.text,
                                "role": role_el.get("codeListValue", "") if role_el is not None else ""
                            })
                if orgs:
                    result["contacts"] = orgs

                # Keywords
                keywords = []
                for kw in root.findall(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:descriptiveKeywords/gmd:MD_Keywords/gmd:keyword/gco:CharacterString", ISO_NS):
                    if kw.text:
                        keywords.append(kw.text)
                if keywords:
                    result["keywords"] = keywords

                # Spatial bounding box
                west = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:extent/gmd:EX_Extent/gmd:geographicElement/gmd:EX_GeographicBoundingBox/gmd:westBoundLongitude/gco:Decimal", ISO_NS)
                east = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:extent/gmd:EX_Extent/gmd:geographicElement/gmd:EX_GeographicBoundingBox/gmd:eastBoundLongitude/gco:Decimal", ISO_NS)
                south = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:extent/gmd:EX_Extent/gmd:geographicElement/gmd:EX_GeographicBoundingBox/gmd:southBoundLatitude/gco:Decimal", ISO_NS)
                north = root.find(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:extent/gmd:EX_Extent/gmd:geographicElement/gmd:EX_GeographicBoundingBox/gmd:northBoundLatitude/gco:Decimal", ISO_NS)

                bbox = {}
                if west is not None and west.text: bbox["west"] = west.text
                if east is not None and east.text: bbox["east"] = east.text
                if south is not None and south.text: bbox["south"] = south.text
                if north is not None and north.text: bbox["north"] = north.text
                if bbox:
                    result["spatialBoundingBox"] = bbox

                # Use limitations
                limits = []
                for lim in root.findall(".//gmd:identificationInfo/gmd:MD_DataIdentification/gmd:resourceConstraints/gmd:MD_LegalConstraints/gmd:useLimitation/gco:CharacterString", ISO_NS):
                    if lim.text:
                        limits.append(lim.text)
                if limits:
                    result["useLimitations"] = limits

                # Distribution format
                formats = []
                for fmt in root.findall(".//gmd:distributionInfo/gmd:MD_Distribution/gmd:distributionFormat/gmd:MD_Format/gmd:name/gco:CharacterString", ISO_NS):
                    if fmt.text:
                        formats.append(fmt.text)
                if formats:
                    result["distributionFormats"] = formats

                # Online resources
                resources = []
                for olr in root.findall(".//gmd:distributionInfo/gmd:MD_Distribution/gmd:transferOptions/gmd:MD_DigitalTransferOptions/gmd:onLine/gmd:CI_OnlineResource", ISO_NS):
                    link_el = olr.find("gmd:linkage/gmd:URL", ISO_NS)
                    name_el = olr.find("gmd:name/gco:CharacterString", ISO_NS)
                    desc_el = olr.find("gmd:description/gco:CharacterString", ISO_NS)
                    func_el = olr.find("gmd:function/gmd:CI_OnLineFunctionCode", ISO_NS)
                    res_info = {}
                    if link_el is not None and link_el.text:
                        res_info["url"] = link_el.text
                    if name_el is not None and name_el.text:
                        res_info["name"] = name_el.text
                    if desc_el is not None and desc_el.text:
                        res_info["description"] = desc_el.text
                    if func_el is not None:
                        res_info["function"] = func_el.get("codeListValue", "")
                    if res_info:
                        resources.append(res_info)
                if resources:
                    result["onlineResources"] = resources

                if result:
                    return {"source": "NOAA-NCEI-ISO", "data": result}

            except ET.ParseError:
                pass

    # --- Strategy 2: NCEI Metadata Landing Page (JSON-LD extraction) ---
    if ncei_metadata_id:
        landing_url = f"https://www.ncei.noaa.gov/access/metadata/landing-page/bin/iso?id={urllib.parse.quote(ncei_metadata_id, safe='')}"
        resp = self._get_with_retry(landing_url)
        if resp is not None and resp.status_code == 200:
            html = resp.text
            jsonld_match = re.search(
                r'<script[^>]*type="application/ld\+json"[^>]*>(.*?)</script>',
                html, re.DOTALL
            )
            if jsonld_match:
                try:
                    jsonld = json.loads(jsonld_match.group(1))
                    result = {
                        "title": jsonld.get("name", ""),
                        "description": jsonld.get("description", ""),
                        "identifier": jsonld.get("identifier", ""),
                        "alternateName": jsonld.get("alternateName", ""),
                        "url": jsonld.get("url", ""),
                        "dateCreated": jsonld.get("dateCreated", ""),
                        "datePublished": jsonld.get("datePublished", ""),
                        "dateModified": jsonld.get("dateModified", ""),
                        "version": jsonld.get("version", ""),
                        "keywords": jsonld.get("keywords", ""),
                        "license": jsonld.get("license", ""),
                    }
                    creators = jsonld.get("creator", [])
                    if isinstance(creators, list):
                        result["creators"] = [c.get("name", "") for c in creators if isinstance(c, dict)]
                    elif isinstance(creators, dict):
                        result["creators"] = [creators.get("name", "")]

                    dist = jsonld.get("distribution", [])
                    if isinstance(dist, list):
                        result["distribution"] = [
                            {"contentUrl": d.get("contentUrl", ""), "encodingFormat": d.get("encodingFormat", "")}
                            for d in dist if isinstance(d, dict)
                        ]

                    spatial = jsonld.get("spatialCoverage", {})
                    if spatial:
                        result["spatialCoverage"] = {
                            "geo": spatial.get("geo", {}),
                            "description": spatial.get("description", "")
                        }

                    return {"source": "NOAA-NCEI-LandingPage", "data": result}
                except (json.JSONDecodeError, KeyError):
                    pass

    # --- Strategy 3: DataCite API (from DOI) ---
    if doi:
        datacite_url = f"https://api.datacite.org/dois/{doi}"
        resp = self._get_with_retry(datacite_url)
        if resp is not None and resp.status_code == 200:
            try:
                dc_data = resp.json()
                attrs = dc_data.get("data", {}).get("attributes", {})
                if attrs:
                    result = {
                        "title": (attrs.get("titles", [{}])[0].get("title", "") if attrs.get("titles") else ""),
                        "doi": attrs.get("doi", doi),
                        "publisher": attrs.get("publisher", ""),
                        "publicationYear": attrs.get("publicationYear", ""),
                        "creators": [c.get("name", "") for c in attrs.get("creators", [])],
                        "description": "",
                        "subjects": [s.get("subject", "") for s in attrs.get("subjects", [])],
                        "language": attrs.get("language", ""),
                        "version": attrs.get("version", ""),
                        "url": attrs.get("url", ""),
                        "formats": attrs.get("formats", []),
                        "sizes": attrs.get("sizes", []),
                        "dates": [{"date": d.get("date", ""), "dateType": d.get("dateType", "")} for d in attrs.get("dates", [])],
                        "rightsList": [{"rights": r.get("rights", ""), "rightsUri": r.get("rightsUri", "")} for r in attrs.get("rightsList", [])],
                        "relatedIdentifiers": [
                            {"relatedIdentifier": ri.get("relatedIdentifier", ""), "relatedIdentifierType": ri.get("relatedIdentifierType", ""), "relationType": ri.get("relationType", "")}
                            for ri in attrs.get("relatedIdentifiers", [])
                        ],
                    }
                    for d in attrs.get("descriptions", []):
                        if d.get("descriptionType") == "Abstract":
                            result["description"] = d.get("description", "")
                            break
                    return {"source": "NOAA-NCEI-DataCite", "data": result}
            except (json.JSONDecodeError, KeyError):
                pass

    return {"error": "Unable to retrieve collection-level metadata from NCEI APIs using available parameters."}

