def fetch_laads_daac(self, **kwargs):
    import re

    # ============================================================
    # 多态参数解析：从多种可能来源提取产品短名 (product shortname)
    # ============================================================
    product_name = None

    # 路径 1: 直接从 dataset_name 获取
    if kwargs.get('dataset_name'):
        candidate = kwargs.get('dataset_name').strip()
        # 验证看起来像一个产品短名（通常是大写字母+数字组合，如 VNP46A2, MOD09GA）
        if re.match(r'^[A-Za-z0-9_]+$', candidate):
            product_name = candidate

    # 路径 2: 从 dataset_url 正则提取 /products/{shortname}
    if not product_name and kwargs.get('dataset_url'):
        url = kwargs.get('dataset_url')
        match = re.search(r'/products/([^/?#]+)', url)
        if match:
            product_name = match.group(1).strip()

    # 路径 3: 从 doi_landing_page 正则提取
    if not product_name and kwargs.get('doi_landing_page'):
        url = kwargs.get('doi_landing_page')
        match = re.search(r'/products/([^/?#]+)', url)
        if match:
            product_name = match.group(1).strip()

    # 路径 4: 从 DOI 中提取 (格式: 10.XXXX/.../PRODUCT.VERSION)
    if not product_name and kwargs.get('doi'):
        doi = kwargs.get('doi')
        # 匹配 DOI 中最后一个 / 之后的短名（不含版本号），如 VNP46A2
        match = re.search(r'/([A-Za-z0-9_]+)\.\d+$', doi)
        if match:
            product_name = match.group(1).strip()
        if not product_name:
            # 备用：匹配倒数第二个路径段
            parts = doi.split('/')
            if len(parts) >= 2:
                candidate = parts[-1]
                # 去掉可能的版本号后缀
                candidate = re.sub(r'\.\d+$', '', candidate)
                if re.match(r'^[A-Za-z0-9_]+$', candidate):
                    product_name = candidate

    # 防御性检查
    if not product_name:
        return {"error": "缺少关键参数，无法解析出产品短名 (product shortname)。请提供 dataset_name, dataset_url, doi_landing_page 或 doi。"}

    # ============================================================
    # 主 API: LAADS DAAC API-V2 产品元数据
    # ============================================================
    main_url = f"https://ladsweb.modaps.eosdis.nasa.gov/api/v2/measurements/products/{product_name}"
    main_resp = self._get_with_retry(main_url)
    main_data = main_resp.json()

    # ============================================================
    # 辅助 API: NASA CMR 集合级元数据 (LAADS DAAC 官方提交元数据的仓库)
    # ============================================================
    aux_url = f"https://cmr.earthdata.nasa.gov/search/collections.json?short_name={product_name}&provider=LAADS"
    try:
        aux_resp = self._get_with_retry(aux_url, timeout=10)
        aux_data = aux_resp.json()
    except Exception as e:
        aux_data = {"error": f"辅助 API (CMR) 获取失败: {e}"}

    return {
        "source": "LAADS DAAC",
        "format": "composite",
        "data": {"primary": main_data, "auxiliary": aux_data}
    }

