def fetch_figshare(self, **kwargs):
    import requests
    import json
    import re

    dataset_url = kwargs.get('dataset_url', '')
    doi_landing_page = kwargs.get('doi_landing_page', '')
    dataset_name = kwargs.get('dataset_name', '')
    doi = kwargs.get('doi', '')

    if not dataset_url and not dataset_name and not doi_landing_page and not doi:
        return {"error": "Missing required parameters"}

    figshare_id = None
    entity_type = None
    urls_to_check = []
    if dataset_url:
        urls_to_check.append(dataset_url)
    if doi_landing_page and doi_landing_page != dataset_url:
        urls_to_check.append(doi_landing_page)

    # === 路径1: URL 正则提取 Figshare 实体 ID ===
    for url in urls_to_check:
        if not url:
            continue
        m = re.search(
            r'figshare\.com/(?:articles/(?:dataset|figure|media|poster|paper|presentation|fileset)/)?(\d+)',
            url
        )
        if m:
            figshare_id = int(m.group(1))
            entity_type = 'article'
            break
        m = re.search(r'figshare\.com/projects/[^/]+/(\d+)', url)
        if m:
            figshare_id = int(m.group(1))
            entity_type = 'project'
            break
        m = re.search(r'figshare\.com/collections/[^/]+/(\d+)', url)
        if m:
            figshare_id = int(m.group(1))
            entity_type = 'collection'
            break

    if figshare_id and entity_type:
        if entity_type == 'project':
            api_url = f'https://api.figshare.com/v2/projects/{figshare_id}'
        elif entity_type == 'collection':
            api_url = f'https://api.figshare.com/v2/collections/{figshare_id}'
        else:
            api_url = f'https://api.figshare.com/v2/articles/{figshare_id}'
        try:
            response = self._get_with_retry(api_url)
            response.raise_for_status()
            data = response.json()
            return {"source": "Figshare", "format": "json", "data": data}
        except Exception as e:
            return {"error": f"Figshare API request failed: {str(e)}"}

    # === 路径2: DOI 中提取 Figshare ID ===
    if doi and doi.strip():
        m = re.search(r'figshare\.(\d+)', doi.strip())
        if m:
            figshare_id = int(m.group(1))
            try:
                api_url = f'https://api.figshare.com/v2/articles/{figshare_id}'
                response = self._get_with_retry(api_url)
                response.raise_for_status()
                return {"source": "Figshare", "format": "json", "data": response.json()}
            except Exception as e:
                return {"error": f"Figshare API request failed: {str(e)}"}

    # === 路径3: 搜索发现 ===
    search_terms = []
    if dataset_name and dataset_name.strip():
        eng = re.sub(r'[^\x00-\x7F]+', '', dataset_name).strip()
        if eng and len(eng) >= 2:
            search_terms.append(eng)

    for url in urls_to_check:
        if url and 'figshare.com' not in url:
            m = re.search(r'https?://(?:www\.)?([^/]+)', url)
            if m:
                for part in m.group(1).split('.'):
                    if part and part not in ('www','com','org','net','edu','gov','io') and len(part) > 2:
                        if part.lower() not in [t.lower() for t in search_terms]:
                            search_terms.append(part)

    if not search_terms:
        return {"error": "Cannot resolve Figshare entity: URL is not a figshare.com link and no searchable terms available"}

    seen = set()
    unique_terms = []
    for t in search_terms:
        if t.lower() not in seen:
            seen.add(t.lower())
            unique_terms.append(t)

    best_project_id = None
    best_article_id = None

    for term in unique_terms:
        try:
            search_resp = requests.post(
                'https://api.figshare.com/v2/articles/search',
                json={"search_for": term, "page_size": 10},
                timeout=20
            )
            if search_resp.status_code != 200:
                continue
            results = search_resp.json()
            if not results:
                continue

            term_lower = term.lower()
            for item in results:
                pid = item.get('project_id')
                aid = item.get('id')
                title = (item.get('title') or '').lower()
                description = (item.get('description') or '').lower()

                if best_project_id is None and pid and pid > 0:
                    if term_lower in title or term_lower in description:
                        best_project_id = pid

                if best_article_id is None:
                    if term_lower in title or term_lower in description:
                        best_article_id = aid

            if best_project_id:
                break

            if best_article_id is None and results:
                best_article_id = results[0].get('id')
        except Exception:
            continue

    if best_project_id:
        try:
            api_url = f'https://api.figshare.com/v2/projects/{best_project_id}'
            response = self._get_with_retry(api_url)
            if response.status_code == 200:
                return {"source": "Figshare", "format": "json", "data": response.json()}
        except Exception:
            pass

    if best_article_id:
        try:
            api_url = f'https://api.figshare.com/v2/articles/{best_article_id}'
            response = self._get_with_retry(api_url)
            if response.status_code == 200:
                return {"source": "Figshare", "format": "json", "data": response.json()}
        except Exception as e:
            return {"error": f"Figshare article API failed: {str(e)}"}

    return {"error": "Could not resolve Figshare entity from provided parameters"}

