        cleaned = re.sub(r'\s+', ' ', cleaned).strip()

        if 'Cropland Data Layer' in cleaned or 'CDL' in cleaned:
            search_term = 'Cropland Data Layer'
        elif cleaned:
            # 取前几个关键词
            words = cleaned.split()
            search_term = ' '.join(words[:4])

    if not search_term and dataset_url:
        # 从 URL 尝试提取平台名
        if 'croplandcros' in dataset_url.lower():
            search_term = 'Cropland Data Layer'

    if not search_term:
