def fetch_nhdplus_hr(self, **kwargs):
    """
    Fetch NHDPlus HR collection-level metadata from USGS ScienceBase Catalog.
    Uses DOI to resolve to ScienceBase item ID, then fetches full metadata.
    """
    import re
    import json

    doi = kwargs.get('doi')
    dataset_url = kwargs.get('dataset_url')
    doi_landing_page = kwargs.get('doi_landing_page')

    # Step 1: Resolve DOI to ScienceBase item ID using Handle API
    if not doi:
        return {"error": "DOI is required to resolve ScienceBase item ID"}

    handle_url = f"https://doi.org/api/handles/{doi}"

    try:
        handle_resp = self._get_with_retry(handle_url)
        handle_data = handle_resp.json()
    except Exception as e:
        return {"error": f"Failed to resolve DOI via Handle API: {e}"}

    # Extract the URL value from Handle response
    sciencebase_url = None
    if handle_data and 'values' in handle_data:
        for val in handle_data['values']:
            if val.get('type') == 'URL':
                sciencebase_url = val.get('data', {}).get('value')
                break

    if not sciencebase_url:
        return {"error": "Could not extract ScienceBase URL from DOI resolution"}

    # Extract ScienceBase item ID from URL
    # URL format: https://www.sciencebase.gov/catalog/item/62c6050cd34eeb1417baff15
    item_id_match = re.search(r'/catalog/item/([a-zA-Z0-9]+)', sciencebase_url)
    if not item_id_match:
        return {"error": f"Could not extract ScienceBase item ID from URL: {sciencebase_url}"}

    item_id = item_id_match.group(1)

    # Step 2: Fetch full metadata from ScienceBase Catalog API
    sb_api_url = f"https://www.sciencebase.gov/catalog/item/{item_id}?format=json"

    try:
        sb_resp = self._get_with_retry(sb_api_url)
        return {
            "source": "USGS ScienceBase Catalog",
            "format": "json",
            "data": sb_resp.json()
        }
    except Exception as e:
        return {"error": f"Failed to fetch metadata from ScienceBase: {e}"}

def fetch_nhdplus_hr(self, **kwargs):
    """
    Fetch NHDPlus HR collection-level metadata from USGS ScienceBase Catalog REST API.

    Workflow:
    1. Resolve DOI 10.5066/P9WFOBQI via Handle API to get ScienceBase item URL
    2. Extract ScienceBase item ID from URL
    3. Fetch full metadata JSON from ScienceBase Catalog REST API

    ScienceBase is the authoritative metadata catalog for all USGS data releases.
    """
    import re
    import json

    doi = kwargs.get('doi')
    dataset_url = kwargs.get('dataset_url')
    doi_landing_page = kwargs.get('doi_landing_page')

    # ---- Step 1: Resolve DOI to get ScienceBase item URL ----
    if not doi:
        return {"error": "DOI is required to resolve ScienceBase Catalog item"}

    handle_url = f"https://doi.org/api/handles/{doi}"

    try:
        handle_resp = self._get_with_retry(handle_url)
        handle_data = handle_resp.json()
    except Exception as e:
        return {"error": f"Failed to resolve DOI via Handle API: {e}"}

    # Extract URL from Handle API response
    sciencebase_url = None
    values = handle_data.get('values', [])
    if not values:
        return {"error": "Handle API response missing 'values' field"}

    for val in values:
        if val.get('type') == 'URL':
            sciencebase_url = val.get('data', {}).get('value')
            break

    if not sciencebase_url:
        return {"error": "Could not extract ScienceBase URL from DOI Handle response"}

    # ---- Step 2: Extract item ID from ScienceBase URL ----
    item_id_match = re.search(r'/catalog/item/([a-zA-Z0-9]+)', sciencebase_url)
    if not item_id_match:
        return {"error": f"Could not extract ScienceBase item ID from URL: {sciencebase_url}"}

    item_id = item_id_match.group(1)

    # ---- Step 3: Fetch metadata from ScienceBase Catalog REST API ----
    sb_api_url = f"https://www.sciencebase.gov/catalog/item/{item_id}?format=json"

    try:
        sb_resp = self._get_with_retry(sb_api_url)
        return {
            "source": "USGS ScienceBase Catalog",
            "format": "json",
            "data": sb_resp.json()
        }
    except json.JSONDecodeError as je:
        return {"error": f"ScienceBase response is not valid JSON: {je}"}
    except Exception as e:
        return {"error": f"Failed to fetch metadata from ScienceBase Catalog API: {e}"}

def fetch_nhdplus_hr(self, **kwargs):
    """
    Fetch NHDPlus HR collection-level metadata from the USGS ScienceBase Catalog REST API.

    Resolution chain:
       DOI (10.5066/P9WFOBQI)
         -> Handle API (doi.org/api/handles/)
           -> ScienceBase item URL
             -> ScienceBase Catalog REST API (/catalog/item/{id}?format=json)

    ScienceBase is the authoritative metadata catalog for all USGS data releases
    and serves as the central directory for The National Map datasets.
    """
    import re
    import json

    doi = kwargs.get('doi')
    dataset_url = kwargs.get('dataset_url')
    doi_landing_page = kwargs.get('doi_landing_page')
