import re
import urllib.parse

def fetch_noaa_psl_reanalysis(self, **kwargs):
    """
    从 NOAA ERDDAP (CoastWatch) 获取 NCEP/NCAR Reanalysis 等 PSL 数据集的 ISO 19115 元数据。

    入参：dataset_url, dataset_name, doi, doi_landing_page
    出参：{"source": ..., "format": "xml", "data": ...}
    """
    dataset_url = kwargs.get('dataset_url')
    dataset_name = kwargs.get('dataset_name')

    # 构建搜索关键词
    search_term = None

    if dataset_url:
        url_match = re.search(r'/Datasets/([^/]+)', dataset_url)
        if url_match:
            path_segment = url_match.group(1)
            search_term = path_segment.replace('.', ' ').replace('_', ' ')

    if not search_term and dataset_name:
        name_lower = dataset_name.lower()
        if 'ncep' in name_lower and 'reanalysis' in name_lower:
            search_term = 'ncep reanalysis'
        elif 'ncep' in name_lower and 'doe' in name_lower:
            search_term = 'ncep doe reanalysis'
        elif 'narr' in name_lower:
            search_term = 'narr reanalysis'
        elif '20th' in name_lower or '20th century' in name_lower:
            search_term = '20th century reanalysis'

    if not search_term:
        return {"error": "无法从输入参数中提取搜索关键词，请检查 dataset_url 或 dataset_name"}

    # ERDDAP 搜索
    encoded_term = urllib.parse.quote(search_term)
    search_url = f"https://coastwatch.pfeg.noaa.gov/erddap/search/index.json?searchFor={encoded_term}&page=1&itemsPerPage=10"

    try:
        search_response = self._get_with_retry(search_url)
        search_data = search_response.json()
    except Exception as e:
        return {"error": f"ERDDAP 搜索请求失败: {e}"}

    # 解析搜索结果
    rows = search_data.get('table', {}).get('rows', [])
    if not rows or len(rows) == 0:
        return {"error": "ERDDAP 搜索无结果"}

    # 匹配最佳数据集
    dataset_id = None

    # 根据搜索关键词确定匹配规则
    if 'ncep' in search_term and 'doe' not in search_term:
        target_title_pattern = 'NCEP/NCAR Reanalysis'
    elif 'ncep' in search_term and 'doe' in search_term:
        target_title_pattern = 'NCEP/DOE Reanalysis'
    elif 'narr' in search_term:
        target_title_pattern = 'NARR'
    elif '20th' in search_term:
        target_title_pattern = '20th Century Reanalysis'
    else:
        target_title_pattern = search_term

    for row in rows:
        if len(row) < 17:
            continue
        title = row[7] if row[7] else ''
        row_dataset_id = row[16] if row[16] else ''

        if target_title_pattern.lower() in title.lower() and row_dataset_id:
            # 优先选择更短、更"主要"的 dataset ID（不带后缀变体）
            if not dataset_id or len(row_dataset_id) < len(dataset_id):
                dataset_id = row_dataset_id

    if not dataset_id:
        return {"error": f"在 ERDDAP 搜索结果中未找到匹配 '{target_title_pattern}' 的数据集"}

    # 获取 ISO 19115 元数据
    iso_url = f"https://coastwatch.pfeg.noaa.gov/erddap/griddap/{dataset_id}.iso19115"

    try:
        iso_response = self._get_with_retry(iso_url)
    except Exception as e:
        return {"error": f"获取 ISO 19115 元数据请求失败: {e}"}

    return {
        "source": "NOAA ERDDAP (CoastWatch) / NOAA ESRL PSL",
        "format": "xml",
        "data": iso_response.text
    }

