    Fetch collection-level metadata from NASA CMR (Common Metadata Repository)
    for LP DAAC / EOSDIS datasets. Uses CMR UMM JSON API with DOI as primary key.
    """
    import re
    import urllib.parse

    doi = kwargs.get('doi')
    dataset_url = kwargs.get('dataset_url')
    doi_landing_page = kwargs.get('doi_landing_page')
    dataset_name = kwargs.get('dataset_name')

    cmr_search_base = "https://cmr.earthdata.nasa.gov/search/collections.umm_json"

    # ===== Path 1: Use DOI directly with CMR search API (preferred, richest) =====
    if doi and doi.strip():
        clean_doi = doi.strip()
        api_url = f"{cmr_search_base}?doi={urllib.parse.quote(clean_doi, safe='')}"
        response = self._get_with_retry(api_url)
        try:
            data = response.json()
        except Exception:
            data = response.text
        return {
            "source": "NASA CMR (LP DAAC)",
            "format": "json",
            "data": data
        }

    # ===== Path 2: Extract concept_id from doi_landing_page HTML meta tags =====
    concept_id = None
    if doi_landing_page and doi_landing_page.strip():
        try:
            html_response = self._get_with_retry(doi_landing_page.strip())
            html_text = html_response.text

