            if not concept_id:
                match = re.search(
                    r'(?:CMR\s*Concept\s*ID|concept[_\-]?id)\s*[:=]\s*([A-Z0-9]+-[A-Z0-9]+)',
                    html_text,
                    re.IGNORECASE
                )
                if match:
                    concept_id = match.group(1)
        except Exception:
            pass

    # ===== Path 3: Extract concept_id from dataset_url (if it is an earthdata URL) =====
    if not concept_id and dataset_url and dataset_url.strip():
        url_candidate = dataset_url.strip()
        # Only attempt if it looks like a URL
        if url_candidate.startswith('http'):
            try:
                html_response = self._get_with_retry(url_candidate)
                html_text = html_response.text

                match = re.search(
