                    )
                    if match:
                        concept_id = match.group(1)
            except Exception:
                pass

    # ===== Path 4: Use dataset_name to search CMR by keyword =====
    if not concept_id and dataset_name and dataset_name.strip():
        # Clean the name: remove parenthetical notes and limit length
        clean_name = re.sub(r'[（(][^)）]*[)）]', '', dataset_name).strip()
