    slug = None

    # Try extracting from dataset_url
    if dataset_url:
        match = re.search(r'/projects/([^/]+)', dataset_url)
        if match:
            slug = match.group(1).strip()

    # Fallback: try doi_landing_page
    if not slug and doi_landing_page:
        match = re.search(r'/projects/([^/]+)', doi_landing_page)
        if match:
            slug = match.group(1).strip()

    if not slug:
        return {
            "error": (
                "无法从传入参数中解析出项目标识符(slug)。"
                "请提供包含 /projects/{slug}/ 模式的 dataset_url 或 doi_landing_page。"
            )
        }

    # --- Step 2: Build the target docs URL pattern ---
    target_docs_url = f"https://gee-community-catalog.org/projects/{slug}/"

