    for line in raw_text.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            entry = json.loads(line)
        except json.JSONDecodeError:
            continue

        docs = entry.get('docs', '')
        if docs and docs.rstrip('/') == target_docs_url.rstrip('/'):
            return {
                "source": "GEE Community Catalog",
                "format": "json",
                "data": entry
            }

    # --- Step 5: Fallback: match by dataset_name substring in title ---
