                continue
            title = entry.get('title', '')
            if title and dataset_name.lower() in title.lower():
                return {
                    "source": "GEE Community Catalog",
                    "format": "json",
                    "data": entry
                }

    return {"error": f"未在目录中找到匹配 slug='{slug}' 的数据集条目"}

