    then retrieves full metadata via package_show.
    """
    dataset_name = kwargs.get('dataset_name', '')
    dataset_url = kwargs.get('dataset_url', '')
    doi = kwargs.get('doi', '')
    doi_landing_page = kwargs.get('doi_landing_page', '')

    # ---- Build search query from available inputs ----
    search_terms = []

    if dataset_name:
        name_lower = dataset_name.lower()
        if 'hrsl' in name_lower:
            search_terms.append('hrsl')
        if 'high resolution settlement layer' in name_lower:
            search_terms.append('"High Resolution Settlement Layer"')
        if not search_terms and 'population' in name_lower:
            search_terms.append('"population density"')

    if not search_terms and dataset_url:
        url_lower = dataset_url.lower()
        if 'high-resolution-population-density' in url_lower or 'population-density' in url_lower:
            search_terms.append('"population density"')
        if 'hrsl' in url_lower:
            search_terms.append('hrsl')

    # If no search terms could be extracted, return error
    if not search_terms:
        return {"error": "缺少关键参数：无法从 dataset_name 或 dataset_url 中提取搜索关键词以定位 HRSL 数据集"}

    query = ' OR '.join(search_terms)

    # ---- Step 1: Search for matching HRSL dataset under Meta organization ----
    search_url = (
        f"https://data.humdata.org/api/3/action/package_search"
        f"?q={query}&fq=organization:meta&rows=1"
    )

    resp = self._get_with_retry(search_url)

    try:
        search_data = resp.json()
    except json.JSONDecodeError:
        return {"error": "HDX search API returned non-JSON response", "status": "parse_error"}

    if not search_data.get('success'):
        return {"error": "HDX search API indicated failure", "raw": search_data}

    result = search_data.get('result', {})
    if result.get('count', 0) == 0:
        return {"error": "No HRSL datasets found on HDX under Meta organization"}

    results = result.get('results', [])
    if not results or len(results) == 0:
        return {"error": "Search results list is empty"}

    package_name = results[0].get('name')
    if not package_name:
        return {"error": "Could not extract package name/ID from search results"}

    # ---- Step 2: Get full package metadata via package_show ----
    show_url = f"https://data.humdata.org/api/3/action/package_show?id={package_name}"
    show_resp = self._get_with_retry(show_url)

    try:
        show_data = show_resp.json()
    except json.JSONDecodeError:
        return {"error": "HDX package_show API returned non-JSON response", "status": "parse_error"}

    if not show_data.get('success'):
        return {"error": "HDX package_show API indicated failure", "raw": show_data}

    return {
        "source": "HDX (Humanitarian Data Exchange)",
        "format": "json",
        "data": show_data
    }

def fetch_ges_disc(self, **kwargs):
    """
    通过 NASA CMR API 获取 GES DISC 数据集的 Collection-level 元数据。

    入参（由外部系统注入）:
        - doi: 官方 DOI (如 10.5067/SXAVCZFAQLNO)
        - dataset_url: 数据集原始链接
        - dataset_name: 数据集名称
        - doi_landing_page: DOI 解析落地页

    返回:
        dict: {"source": "NASA CMR (GES DISC)", "format": "json", "data": {...}}
    """
    import re
    import json
    import xml.etree.ElementTree as ET

    doi = kwargs.get('doi')
    dataset_url = kwargs.get('dataset_url', '')
    dataset_name = kwargs.get('dataset_name', '')

    concept_id = None

    # =========================================================
    # Path 1: 使用 DOI 在 CMR 中搜索 (最高优先级)
    # =========================================================
    if doi:
        try:
            search_url = f"https://cmr.earthdata.nasa.gov/search/collections?doi={doi}"
            resp = self._get_with_retry(search_url)
            if resp is not None and resp.status_code == 200:
                root = ET.fromstring(resp.text)
                ref = root.find('.//reference')
                if ref is not None:
                    id_elem = ref.find('id')
                    if id_elem is not None and id_elem.text:
                        concept_id = id_elem.text.strip()
        except Exception:
            pass

    # =========================================================
    # Path 2: 从 dataset_url 中提取 short_name，再用 CMR short_name 搜索
    # =========================================================
    if not concept_id and dataset_url:
        # GES DISC URL 模式: .../datacollection/GLDAS_NOAH025_M_2.1.html
        m = re.search(r'datacollection/([A-Za-z0-9_]+?)(?:_\d+\.\d+)?\.html', dataset_url)
        if not m:
            # 尝试更宽松的匹配
            m = re.search(r'/([A-Za-z0-9_]+?)(?:_\d+\.\d+)?\.html', dataset_url)
        if m:
            short_name = m.group(1)
            try:
                search_url = f"https://cmr.earthdata.nasa.gov/search/collections?short_name={short_name}"
                resp = self._get_with_retry(search_url)
                if resp is not None and resp.status_code == 200:
                    root = ET.fromstring(resp.text)
                    ref = root.find('.//reference')
                    if ref is not None:
                        id_elem = ref.find('id')
                        if id_elem is not None and id_elem.text:
                            concept_id = id_elem.text.strip()
            except Exception:
                pass

    # =========================================================
    # Path 3: 使用 dataset_name 作为 keyword 在 CMR 中搜索
    # =========================================================
    if not concept_id and dataset_name:
        try:
            search_url = f"https://cmr.earthdata.nasa.gov/search/collections?keyword={dataset_name}"
            resp = self._get_with_retry(search_url)
            if resp is not None and resp.status_code == 200:
                root = ET.fromstring(resp.text)
                ref = root.find('.//reference')
                if ref is not None:
                    id_elem = ref.find('id')
                    if id_elem is not None and id_elem.text:
                        concept_id = id_elem.text.strip()
        except Exception:
            pass

    # =========================================================
    # 如果所有路径都无法解析出 concept_id，返回错误
    # =========================================================
    if not concept_id:
        return {"error": "无法从提供的参数解析出 CMR concept_id，请提供有效的 DOI、dataset_url 或 dataset_name"}

    # =========================================================
    # 使用 concept_id 获取完整 UMM JSON 元数据
    # =========================================================
    umm_url = f"https://cmr.earthdata.nasa.gov/search/concepts/{concept_id}.umm_json"
    resp = self._get_with_retry(umm_url)

    if resp is None or resp.status_code != 200:
        return {"error": f"获取 UMM JSON 元数据失败，HTTP 状态码: {resp.status_code if resp else 'N/A'}"}

    try:
        data = resp.json()
    except json.JSONDecodeError as e:
        return {"error": f"响应无法解析为 JSON: {str(e)}", "raw": resp.text[:500]}

    return {
        "source": "NASA CMR (GES DISC)",
        "format": "json",
        "data": data
    }

